<?php
/**
 * WPBakery — Advanced MCP abilities.
 *
 * Page settings (the WPBakery-owned _wpb_* post meta), user templates (the
 * native "My Templates" stored in the wpb_js_templates option), and a static
 * reference for the vc_gitem_* Grid Item shortcodes (which aren't in WPBMap).
 * Built from the Novamira reference; not runtime-tested.
 *
 * @package atarim-visual-collaboration
 */

if ( ! defined('ABSPATH') ) {
    exit;
}

class AVCF_Abilities_WPBakery_Pro extends AVCF_Abilities_Base {

    const TEMPLATES_OPTION = 'wpb_js_templates';
    const META_CUSTOM_CSS  = '_wpb_post_custom_css';
    const META_SHORTCODE_CSS = '_wpb_shortcodes_custom_css';

    /** @var AVCF_WPBakery_Detector */
    private $detector;

    public function __construct() {
        $this->detector = new AVCF_WPBakery_Detector();
    }

    public function register() {
        if ( ! $this->detector->avcf_wpbakery_is_available() ) {
            return;
        }
        $this->register_settings();
        $this->register_templates();
        $this->register_grid_item_elements();
    }

    /* ------------------------------ shared ----------------------------- */

    private function ro_meta() {
        return [ 'mcp' => [ 'public' => true, 'type' => 'tool' ], 'annotations' => [ 'readonly' => true, 'destructive' => false, 'idempotent' => true ] ];
    }
    private function write_meta( $destructive = false ) {
        return [ 'mcp' => [ 'public' => true, 'type' => 'tool' ], 'annotations' => [ 'readonly' => false, 'destructive' => (bool) $destructive, 'idempotent' => false ] ];
    }
    private function std_out() {
        return [ 'type' => 'object', 'properties' => [ 'success' => [ 'type' => 'boolean' ], 'message' => [ 'type' => 'string' ] ], 'required' => [ 'success', 'message' ] ];
    }
    private function require_post( $input, $need_edit = false ) {
        $pid = isset( $input['post_id'] ) ? (int) $input['post_id'] : ( isset( $input['post'] ) ? (int) $input['post'] : 0 );
        if ( $pid <= 0 || ! get_post( $pid ) ) { return [ 'err' => [ 'success' => false, 'message' => 'A valid post_id is required.' ] ]; }
        if ( $need_edit && ! ( current_user_can( 'edit_post', $pid ) || current_user_can( 'edit_posts' ) ) ) {
            return [ 'err' => [ 'success' => false, 'message' => 'No permission to edit this post.' ] ];
        }
        return [ 'post_id' => $pid ];
    }

    /* ------------------------------ settings --------------------------- */

    private function register_settings() {
        $self = $this;

        wp_register_ability( 'atarim/wpbakery-get-settings', [
            'label' => 'Get WPBakery Settings', 'category' => 'atarim',
            'description' => 'Read the WPBakery-owned meta on a post: wpbakery_edited (the _wpb_vc_js_status flag), custom_css (page-level CSS the user authors, _wpb_post_custom_css — what most agents care about), and shortcodes_custom_css (auto-generated by WPBakery from each element\'s Design Options, rebuilt on save — read-mostly).',
            'input_schema' => [ 'type' => 'object', 'properties' => [ 'post_id' => [ 'type' => 'integer', 'minimum' => 1 ] ], 'required' => [ 'post_id' ], 'additionalProperties' => false ],
            'output_schema'=> [ 'type' => 'object', 'properties' => [ 'success' => [ 'type' => 'boolean' ], 'post_id' => [ 'type' => 'integer' ], 'wpbakery_edited' => [ 'type' => 'boolean' ], 'custom_css' => [ 'type' => 'string' ], 'shortcodes_custom_css' => [ 'type' => 'string' ], 'message' => [ 'type' => 'string' ] ], 'required' => [ 'success', 'message' ] ],
            'execute_callback' => function( $input = [] ) use ( $self ) {
                $g = $self->require_post( $input ); if ( isset( $g['err'] ) ) { return $g['err']; }
                $pid = $g['post_id'];
                return [
                    'success' => true,
                    'post_id' => $pid,
                    'wpbakery_edited' => get_post_meta( $pid, AVCF_WPBakery_Helpers::META_STATUS, true ) === 'true',
                    'custom_css' => (string) get_post_meta( $pid, AVCF_Abilities_WPBakery_Pro::META_CUSTOM_CSS, true ),
                    'shortcodes_custom_css' => (string) get_post_meta( $pid, AVCF_Abilities_WPBakery_Pro::META_SHORTCODE_CSS, true ),
                    'message' => 'OK.',
                ];
            },
            'permission_callback' => function() { return current_user_can( 'edit_posts' ); },
            'meta' => $this->ro_meta(),
        ] );

        wp_register_ability( 'atarim/wpbakery-set-settings', [
            'label' => 'Set WPBakery Settings', 'category' => 'atarim',
            'description' => 'Update WPBakery post meta. custom_css sets the page-level custom CSS (_wpb_post_custom_css). wpbakery_edited:true marks the post as WPBakery-edited (_wpb_vc_js_status). shortcodes_custom_css can be set but is normally auto-generated and rebuilt by WPBakery on save, so writing it is rarely useful.',
            'input_schema' => [ 'type' => 'object', 'properties' => [
                'post_id'               => [ 'type' => 'integer', 'minimum' => 1 ],
                'custom_css'            => [ 'type' => 'string' ],
                'wpbakery_edited'       => [ 'type' => 'boolean' ],
                'shortcodes_custom_css' => [ 'type' => 'string' ],
            ], 'required' => [ 'post_id' ], 'additionalProperties' => false ],
            'output_schema'=> $this->std_out(),
            'execute_callback' => function( $input = [] ) use ( $self ) {
                $g = $self->require_post( $input, true ); if ( isset( $g['err'] ) ) { return $g['err']; }
                $pid = $g['post_id']; $changed = [];
                if ( isset( $input['custom_css'] ) ) { update_post_meta( $pid, AVCF_Abilities_WPBakery_Pro::META_CUSTOM_CSS, (string) $input['custom_css'] ); $changed[] = 'custom_css'; }
                if ( isset( $input['shortcodes_custom_css'] ) ) { update_post_meta( $pid, AVCF_Abilities_WPBakery_Pro::META_SHORTCODE_CSS, (string) $input['shortcodes_custom_css'] ); $changed[] = 'shortcodes_custom_css'; }
                if ( isset( $input['wpbakery_edited'] ) ) { update_post_meta( $pid, AVCF_WPBakery_Helpers::META_STATUS, ! empty( $input['wpbakery_edited'] ) ? 'true' : 'false' ); $changed[] = 'wpbakery_edited'; }
                if ( empty( $changed ) ) { return [ 'success' => false, 'message' => 'Nothing to update.' ]; }
                return [ 'success' => true, 'message' => 'Updated: ' . implode( ', ', $changed ) . '.' ];
            },
            'permission_callback' => function() { return current_user_can( 'edit_posts' ); },
            'meta' => $this->write_meta( false ),
        ] );
    }

    /* ------------------------------ templates -------------------------- */

    private function templates_read() {
        $raw = get_option( self::TEMPLATES_OPTION, [] );
        return is_array( $raw ) ? $raw : [];
    }
    private function templates_write( $templates ) {
        return (bool) update_option( self::TEMPLATES_OPTION, $templates, false );
    }
    /** Extract the shortcode content from a template entry (key may vary). */
    public static function template_content( $entry ) {
        if ( ! is_array( $entry ) ) { return ''; }
        foreach ( [ 'template', 'content', 'value' ] as $k ) {
            if ( isset( $entry[ $k ] ) && is_string( $entry[ $k ] ) ) { return $entry[ $k ]; }
        }
        return '';
    }

    private function register_templates() {
        $self = $this;

        wp_register_ability( 'atarim/wpbakery-list-templates', [
            'label' => 'List WPBakery Templates', 'category' => 'atarim',
            'description' => 'List WPBakery user "My Templates" (from the wpb_js_templates option). Returns id (use with apply/delete-template) and name.',
            'input_schema' => [ 'type' => 'object', 'properties' => [], 'additionalProperties' => false ],
            'output_schema'=> [ 'type' => 'object', 'properties' => [ 'success' => [ 'type' => 'boolean' ], 'templates' => [ 'type' => 'array' ], 'message' => [ 'type' => 'string' ] ], 'required' => [ 'success', 'message' ] ],
            'execute_callback' => function( $input = [] ) use ( $self ) {
                $out = [];
                foreach ( $self->templates_read_public() as $id => $tpl ) {
                    $out[] = [ 'id' => (string) $id, 'name' => is_array( $tpl ) && isset( $tpl['name'] ) ? (string) $tpl['name'] : (string) $id ];
                }
                return [ 'success' => true, 'templates' => $out, 'message' => sprintf( '%d template(s).', count( $out ) ) ];
            },
            'permission_callback' => function() { return current_user_can( 'edit_posts' ); },
            'meta' => $this->ro_meta(),
        ] );

        wp_register_ability( 'atarim/wpbakery-create-template', [
            'label' => 'Create WPBakery Template', 'category' => 'atarim',
            'description' => 'SITE-WIDE. Save a new WPBakery "My Template". Provide name and the content as either shortcode (a raw WPBakery shortcode string) or tree (nested { tag, atts, children[], content? } nodes, which is serialized).',
            'input_schema' => [ 'type' => 'object', 'properties' => [
                'name'      => [ 'type' => 'string' ],
                'shortcode' => [ 'type' => 'string' ],
                'tree'      => [ 'type' => 'array' ],
            ], 'required' => [ 'name' ], 'additionalProperties' => false ],
            'output_schema'=> [ 'type' => 'object', 'properties' => [ 'success' => [ 'type' => 'boolean' ], 'id' => [ 'type' => 'string' ], 'message' => [ 'type' => 'string' ] ], 'required' => [ 'success', 'message' ] ],
            'execute_callback' => function( $input = [] ) use ( $self ) {
                $content = '';
                if ( isset( $input['shortcode'] ) && is_string( $input['shortcode'] ) ) { $content = $input['shortcode']; }
                elseif ( isset( $input['tree'] ) && is_array( $input['tree'] ) ) { $content = AVCF_WPBakery_Helpers::serialize_content( $self->normalize_nodes( $input['tree'] ) ); }
                else { return [ 'success' => false, 'message' => 'Provide shortcode (string) or tree (array).' ]; }
                $templates = $self->templates_read_public();
                $templates[] = [ 'name' => (string) $input['name'], 'template' => $content ];
                if ( ! $self->templates_write_public( $templates ) ) { return [ 'success' => false, 'message' => 'Failed to save template.' ]; }
                end( $templates );
                return [ 'success' => true, 'id' => (string) key( $templates ), 'message' => 'Template created.' ];
            },
            'permission_callback' => function() { return current_user_can( 'manage_options' ); },
            'meta' => $this->write_meta( false ),
        ] );

        wp_register_ability( 'atarim/wpbakery-apply-template', [
            'label' => 'Apply WPBakery Template', 'category' => 'atarim',
            'description' => 'Insert a saved template\'s content into a post. By default appends the template\'s elements at the top level; pass parent_address to nest them inside a container and position for placement. Pass replace:true to overwrite the whole page with the template instead.',
            'input_schema' => [ 'type' => 'object', 'properties' => [
                'post_id'        => [ 'type' => 'integer', 'minimum' => 1 ],
                'template_id'    => [ 'type' => 'string' ],
                'parent_address' => [ 'type' => 'string' ],
                'position'       => [ 'type' => 'integer', 'minimum' => 0 ],
                'replace'        => [ 'type' => 'boolean', 'default' => false ],
            ], 'required' => [ 'post_id', 'template_id' ], 'additionalProperties' => false ],
            'output_schema'=> $this->std_out(),
            'execute_callback' => function( $input = [] ) use ( $self ) {
                $g = $self->require_post( $input, true ); if ( isset( $g['err'] ) ) { return $g['err']; }
                $templates = $self->templates_read_public();
                $tid = (string) $input['template_id'];
                $entry = null;
                foreach ( $templates as $k => $t ) { if ( (string) $k === $tid ) { $entry = $t; break; } }
                if ( $entry === null ) { return [ 'success' => false, 'message' => sprintf( 'Template "%s" not found.', $tid ) ]; }
                $content = AVCF_Abilities_WPBakery_Pro::template_content( $entry );
                $nodes = AVCF_WPBakery_Helpers::parse_content( $content );
                if ( empty( $nodes ) ) { return [ 'success' => false, 'message' => 'Template has no parseable WPBakery content.' ]; }

                if ( ! empty( $input['replace'] ) ) {
                    if ( ! AVCF_WPBakery_Helpers::write_tree( $g['post_id'], $nodes ) ) { return [ 'success' => false, 'message' => 'Failed to save.' ]; }
                    return [ 'success' => true, 'message' => 'Page replaced with template.' ];
                }
                $tree = AVCF_WPBakery_Helpers::read_tree( $g['post_id'] );
                $parent = isset( $input['parent_address'] ) ? (string) $input['parent_address'] : '';
                if ( $parent !== '' && AVCF_WPBakery_Helpers::tree_get( $tree, $parent ) === null ) { return [ 'success' => false, 'message' => sprintf( 'parent_address "%s" does not resolve.', $parent ) ]; }
                $pos = isset( $input['position'] ) ? (int) $input['position'] : PHP_INT_MAX;
                foreach ( $nodes as $node ) {
                    $tree = AVCF_WPBakery_Helpers::tree_insert( $tree, $parent, $pos, $node );
                    if ( $tree === null ) { return [ 'success' => false, 'message' => 'Insert failed.' ]; }
                    if ( $pos !== PHP_INT_MAX ) { $pos++; }
                }
                if ( ! AVCF_WPBakery_Helpers::write_tree( $g['post_id'], $tree ) ) { return [ 'success' => false, 'message' => 'Failed to save.' ]; }
                return [ 'success' => true, 'message' => sprintf( 'Applied template "%s" (%d top-level element(s)).', $tid, count( $nodes ) ) ];
            },
            'permission_callback' => function() { return current_user_can( 'edit_posts' ); },
            'meta' => $this->write_meta( false ),
        ] );

        wp_register_ability( 'atarim/wpbakery-delete-template', [
            'label' => 'Delete WPBakery Template', 'category' => 'atarim',
            'description' => 'SITE-WIDE. Delete a saved WPBakery template by id. Dry run unless confirm:true.',
            'input_schema' => [ 'type' => 'object', 'properties' => [ 'template_id' => [ 'type' => 'string' ], 'confirm' => [ 'type' => 'boolean', 'default' => false ] ], 'required' => [ 'template_id' ], 'additionalProperties' => false ],
            'output_schema'=> $this->std_out(),
            'execute_callback' => function( $input = [] ) use ( $self ) {
                $templates = $self->templates_read_public();
                $tid = (string) $input['template_id'];
                $exists = false;
                foreach ( $templates as $k => $t ) { if ( (string) $k === $tid ) { $exists = true; break; } }
                if ( ! $exists ) { return [ 'success' => false, 'message' => sprintf( 'Template "%s" not found.', $tid ) ]; }
                if ( empty( $input['confirm'] ) ) { return [ 'success' => true, 'message' => sprintf( 'Dry run: would delete template "%s". Re-call with confirm:true.', $tid ) ]; }
                $new = [];
                foreach ( $templates as $k => $t ) { if ( (string) $k !== $tid ) { $new[] = $t; } }
                if ( ! $self->templates_write_public( $new ) ) { return [ 'success' => false, 'message' => 'Failed to save.' ]; }
                return [ 'success' => true, 'message' => sprintf( 'Template "%s" deleted.', $tid ) ];
            },
            'permission_callback' => function() { return current_user_can( 'manage_options' ); },
            'meta' => $this->write_meta( true ),
        ] );
    }

    /* public wrappers for closures */
    public function templates_read_public() { return $this->templates_read(); }
    public function templates_write_public( $t ) { return $this->templates_write( $t ); }
    public function normalize_nodes( $nodes ) {
        $out = [];
        foreach ( (array) $nodes as $n ) {
            if ( ! is_array( $n ) || ! isset( $n['tag'] ) ) { continue; }
            $node = [ 'tag' => (string) $n['tag'], 'atts' => isset( $n['atts'] ) && is_array( $n['atts'] ) ? $n['atts'] : [], 'children' => isset( $n['children'] ) && is_array( $n['children'] ) ? $this->normalize_nodes( $n['children'] ) : [] ];
            if ( isset( $n['content'] ) && $n['content'] !== '' ) { $node['_content'] = (string) $n['content']; }
            $out[] = $node;
        }
        return $out;
    }

    /* ------------------------- grid-item elements ---------------------- */

    private function register_grid_item_elements() {
        wp_register_ability( 'atarim/wpbakery-list-grid-item-elements', [
            'label' => 'List WPBakery Grid Item Elements', 'category' => 'atarim',
            'description' => 'List the vc_gitem_* shortcodes used inside vc_grid_item template posts (the per-item layout consumed by vc_basic_grid / vc_masonry_grid). These are NOT in WPBMap, so wpbakery-list-elements does not return them — use this when building/editing a grid item. Also returns dynamic_links: the "magic" string values that link atts accept inside a grid_item context (resolved against the loop post at render).',
            'input_schema' => [ 'type' => 'object', 'properties' => [], 'additionalProperties' => false ],
            'output_schema'=> [ 'type' => 'object', 'properties' => [ 'success' => [ 'type' => 'boolean' ], 'elements' => [ 'type' => 'array' ], 'dynamic_links' => [ 'type' => 'object' ], 'message' => [ 'type' => 'string' ] ], 'required' => [ 'success', 'message' ] ],
            'execute_callback' => function( $input = [] ) {
                $elements = [
                    [ 'tag' => 'vc_gitem_row', 'label' => 'Grid Item Row', 'purpose' => 'Row wrapper inside a grid item.', 'is_container' => true, 'atts' => [ 'gap', 'el_class' ] ],
                    [ 'tag' => 'vc_gitem_col', 'label' => 'Grid Item Column', 'purpose' => 'Column inside a grid item row.', 'is_container' => true, 'atts' => [ 'width', 'el_class' ] ],
                    [ 'tag' => 'vc_gitem_zone_a', 'label' => 'Zone A', 'purpose' => 'Primary content zone (often the image/background).', 'is_container' => true, 'atts' => [ 'link', 'el_class' ] ],
                    [ 'tag' => 'vc_gitem_zone_b', 'label' => 'Zone B', 'purpose' => 'Secondary overlay zone.', 'is_container' => true, 'atts' => [ 'link', 'el_class' ] ],
                    [ 'tag' => 'vc_gitem_zone_c', 'label' => 'Zone C', 'purpose' => 'Tertiary zone.', 'is_container' => true, 'atts' => [ 'link', 'el_class' ] ],
                    [ 'tag' => 'vc_gitem_post_image', 'label' => 'Post Image', 'purpose' => 'Featured image of the loop post.', 'is_container' => false, 'atts' => [ 'link', 'img_size' ] ],
                    [ 'tag' => 'vc_gitem_post_title', 'label' => 'Post Title', 'purpose' => 'Title of the loop post.', 'is_container' => false, 'atts' => [ 'text_color', 'css' ] ],
                    [ 'tag' => 'vc_gitem_post_excerpt', 'label' => 'Post Excerpt', 'purpose' => 'Excerpt of the loop post.', 'is_container' => false, 'atts' => [ 'excerpt_length', 'css' ] ],
                    [ 'tag' => 'vc_gitem_post_date', 'label' => 'Post Date', 'purpose' => 'Published date.', 'is_container' => false, 'atts' => [ 'date_format', 'css' ] ],
                    [ 'tag' => 'vc_gitem_post_categories', 'label' => 'Post Categories', 'purpose' => 'Category links.', 'is_container' => false, 'atts' => [ 'css' ] ],
                    [ 'tag' => 'vc_gitem_post_author', 'label' => 'Post Author', 'purpose' => 'Author name/link.', 'is_container' => false, 'atts' => [ 'css' ] ],
                    [ 'tag' => 'vc_gitem_post_meta', 'label' => 'Post Meta', 'purpose' => 'Arbitrary post meta field.', 'is_container' => false, 'atts' => [ 'post_meta_field', 'css' ] ],
                    [ 'tag' => 'vc_gitem_post_data', 'label' => 'Post Data', 'purpose' => 'Generic post data field.', 'is_container' => false, 'atts' => [ 'post_data_source', 'css' ] ],
                    [ 'tag' => 'vc_gitem_animated_block', 'label' => 'Animated Block', 'purpose' => 'Hover-animation wrapper.', 'is_container' => true, 'atts' => [ 'animation', 'css' ] ],
                    [ 'tag' => 'vc_gitem_post_content', 'label' => 'Post Content', 'purpose' => 'Full content of the loop post.', 'is_container' => false, 'atts' => [ 'css' ] ],
                ];
                $dynamic_links = [
                    'values'      => [ 'post_link', 'image', 'image_lightbox', 'custom', 'none' ],
                    'applies_to'  => [ 'vc_btn', 'vc_gitem_post_image', 'vc_gitem_zone_a', 'vc_gitem_zone_b', 'vc_gitem_zone_c' ],
                    'note'        => 'Pass as a plain string (NOT a vc_link object). Resolved against the loop post at render; ignored outside a grid item.',
                ];
                return [ 'success' => true, 'elements' => $elements, 'dynamic_links' => $dynamic_links, 'message' => sprintf( '%d grid-item element(s).', count( $elements ) ) ];
            },
            'permission_callback' => function() { return current_user_can( 'edit_posts' ); },
            'meta' => $this->ro_meta(),
        ] );
    }
}
